import { HttpClient, HttpParams } from "@angular/common/http";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { environment } from "../../environments/environment";

@Injectable({
    providedIn: 'root'
})
export class CalcularService {
    
    private baseUrl = environment.APIEndpoint;
    constructor(private http: HttpClient) { }
    
    calcularTributos(body: any): Observable<any> {
        return this.http.post<any>(`${this.baseUrl}/calculadora/regime-geral`, body, { observe: 'response' });
    }

    calcularTributosPedagio(body: any): Observable<any> {
        return this.http.post<any>(`${this.baseUrl}/calculadora/pedagio`, body, { observe: 'response' });
    }

    /**
     * Formata a data para o formato esperado pelo backend: '2026-01-01T03:00:00-03:00'
     * Horário fixo em 03:00:00 com timezone de Brasília (-03:00)
     */
    formatarDataParaBackend(data: Date): string {
        const ano = data.getFullYear();
        const mes = String(data.getMonth() + 1).padStart(2, '0');
        const dia = String(data.getDate()).padStart(2, '0');
        
        return `${ano}-${mes}-${dia}T03:00:00-03:00`;
    }
}
